attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.00){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 3.5){                                          /* Combust II: a low crown of flames around the target (the torso stays clear), upright, only turned about Y */
        vec3 fw = cameraPosition - aO; fw.y = 0.; fw = normalize(fw); vec3 rt = vec3(fw.z, 0., -fw.x);
        float H = 1.45*(1. + .06*aD.x), W = .8*(1. + .06*aD.x);
        vP = vec2(position.x*W, (position.y*.5 + .5)*H);
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + fw*.12 + rt*vP.x + vec3(0., vP.y, 0.), 1.); return; }
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.75;   /* well in front of the chest: the body never cuts the quad */ float S = .8*(1. + .15*aD.x); mv.xy += position.xy*S; vP = position.xy*.8; gl_Position = projectionMatrix*mv; }
